-- Resumen de lo cargado
select 'clientes' t, count(*) from clientes
union all select 'proyectos', count(*) from proyectos
union all select 'sitios', count(*) from sitios
union all select 'tecnicos', count(*) from tecnicos
union all select 'tipos_actividad', count(*) from tipos_actividad
union all select 'actividades', count(*) from actividades
union all select 'checklist_items', count(*) from checklist_items
union all select 'incidencias', count(*) from incidencias
union all select 'materiales', count(*) from materiales
union all select 'movimientos', count(*) from movimientos_material
union all select 'evidencias', count(*) from evidencias
union all select 'historial', count(*) from historial
union all select 'notificaciones', count(*) from notificaciones;
